import { projectApplicationApprove, type ProjectApplicationApproveRequest } from '~/client';

export const useApproveCanvasser = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync: approveCanvasser, asyncStatus } = useMutation({
    mutation: (approveData: ProjectApplicationApproveRequest) =>
      projectApplicationApprove({
        composable: '$fetch',
        body: ref(approveData),
      }),
    onSuccess: async (data, { project_id }) => {
      queryCache.invalidateQueries({ key: ['project-tabs-status'], exact: false });
      queryCache.invalidateQueries({ key: ['applications.applicants'], exact: false });
      queryCache.invalidateQueries({ key: ['applications.details'], exact: false });
    },
    onError: (error) => {
      console.error('Error approving canvasser:', error);
      showToastError(error);
    },
  });

  return {
    approveCanvasser,
    isApprovingCanvasser: computed(() => asyncStatus.value === 'loading'),
  };
});
