<template>
  <div class="flex flex-col gap-6">
    <AppLoader v-if="isLoading" variant="table" subject="applications" />
    <AppError
      v-else-if="error || !applications"
      title="Failed to load applications"
      :error="error"
      variant="table"
      :action="refetch"
      action-text="Retry"
    />
    <ResponsiveTable v-else rounded>
      <ResponsiveTableHeader>
        <ResponsiveTableHead v-for="header in tableHeaders" :key="header.value">
          <div class="flex items-center gap-2 text-nowrap" :class="header.class">
            {{ header.text }}
          </div>
        </ResponsiveTableHead>
      </ResponsiveTableHeader>
      <ResponsiveTableBody>
        <ResponsiveTableEmpty
          v-if="!applications || applications.total_count === 0"
          :colspan="6"
          :cols="4"
          :cols-sm="4"
          cell-class="text-center"
        >
          <AppEmpty subject="applications" variant="table" />
        </ResponsiveTableEmpty>
        <ResponsiveTableRow v-for="application in applications?.items" :key="application.user_id">
          <ResponsiveTableCell :cols="4" :cols-sm="2" label="Canvasser">
            <component
              :is="isAdmin ? 'NuxtLink' : 'div'"
              :to="isAdmin ? { name: 'users-id', params: { id: application.user_id } } : undefined"
              class="text-base flex items-center gap-2"
            >
              <AvatarImageWrapper
                :src="application.profile_picture_url || ''"
                alt="Profile Image"
                :fallback="`${application.first_name.charAt(0)}${application.last_name.charAt(0)}`"
                size="sm"
              />
              {{ username(application) }}
            </component>
          </ResponsiveTableCell>
          <ResponsiveTableCell :cols="2" :cols-sm="2" label="Application Date" class="md:text-center">
            {{ formatDateTzToFormat(application.application_date, 'MM/dd/yyyy, hh:mm aaa', timezone) }}
          </ResponsiveTableCell>
          <ResponsiveTableCell :cols="2" :cols-sm="2" label="Number of Projects" class="md:text-center">
            {{ application.active_projects_count }}/{{ application.total_projects_count }}
          </ResponsiveTableCell>
          <ResponsiveTableCell :cols="2" :cols-sm="2" label="Status" class="md:text-center">
            <div class="md:flex md:justify-center">
              <Badge :variant="getApplicationStatus(application.status).variant">
                {{ application.status === 'applied' ? 'new' : getApplicationStatus(application.status).label }}
              </Badge>
            </div>
          </ResponsiveTableCell>
          <ResponsiveTableCell :cols="2" :cols-sm="2" label="Onboarding State" class="md:text-center">
            <div class="md:flex md:justify-center">
              <OnboardingState v-if="application.onboarding_state" :onboarding-state="application.onboarding_state" />
            </div>
          </ResponsiveTableCell>
          <ResponsiveTableCell
            :cols="2"
            :cols-sm="2"
            :label="application.status === 'applied' ? 'Actions' : undefined"
            class="md:text-center"
          >
            <div
              v-if="application.status === 'applied'"
              class="flex items-center justify-start md:justify-center gap-2"
            >
              <ApplicationsDetailsApplyDialog
                :application="application"
                :project-id="projectId"
                :payment="payment"
                :project-name="projectName"
                :project-type="projectType"
                :payment-enabled="paymentEnabled"
              >
                <template #default>
                  <Button variant="outline" size="icon" class="border-green-200">
                    <UserRoundCheck class="stroke-green-600" />
                  </Button>
                </template>
              </ApplicationsDetailsApplyDialog>
              <ApplicationsDetailsRejectDialog :application="application" :project-id="projectId">
                <template #default>
                  <Button variant="outline" size="icon" class="border-red-200">
                    <UserRoundX class="stroke-red-400" />
                  </Button>
                </template>
              </ApplicationsDetailsRejectDialog>
            </div>
          </ResponsiveTableCell>
        </ResponsiveTableRow>
      </ResponsiveTableBody>
      <ResponsiveTableFooter
        v-if="total > 0 && (applications?.items.length ?? 0) > 0"
        :colspan="6"
        :cols="4"
        :cols-sm="4"
      >
        <AppPagination :page="page" :size="size" :total="total" label="users" />
      </ResponsiveTableFooter>
    </ResponsiveTable>
  </div>
</template>

<script setup lang="ts">
import { UserRoundCheck, UserRoundX } from 'lucide-vue-next';
import { FetchError } from 'ofetch';
import { getApplicationStatus } from '~/constants/applications';
import { tableHeaders } from '~/constants/applications/details';
import type {
  ProjectType,
  UserApplicationListResponse,
  SignatureUpcomingManagerPricing,
  CanvassingUpcomingManagerPricing,
} from '~/client';

const { timezone, isAdmin } = useUserRole();

withDefaults(
  defineProps<{
    applications?: UserApplicationListResponse;
    isLoading?: boolean;
    error?: FetchError<any> | null;
    refetch?: () => void;
    page: number;
    size: number;
    total: number;
    projectId: string;
    payment: SignatureUpcomingManagerPricing | CanvassingUpcomingManagerPricing;
    projectName?: string;
    projectType: ProjectType;
    paymentEnabled: boolean;
  }>(),
  {
    applications: undefined,
    error: null,
    refetch: undefined,
    projectName: '',
  }
);
</script>
