<template>
  <Dialog v-model:open="isVisible" @update:open="onOpenUpdate">
    <DialogTrigger as-child>
      <slot />
    </DialogTrigger>
    <DialogContent class="gap-6 max-w-xs sm:max-w-sm md:max-w-5xl px-0">
      <DialogHeader class="gap-y-2 text-left">
        <DialogTitle class="text-xl px-6">Approve Application?</DialogTitle>
        <DialogDescription />
      </DialogHeader>
      <form id="applyApplication" class="px-6" @submit.prevent="onApply">
        <AssignmentInfoForm
          mode="create"
          :user-id="application.user_id"
          :user-role="'canvasser'"
          :user-full-name="username(application)"
          :project-id="projectId"
          :project-name="projectName"
          :project-type="projectType"
          :payment="payment"
        />
      </form>
      <DialogFooter class="flex flex-row justify-end gap-2 px-6">
        <DialogClose as-child>
          <Button variant="outline" class="h-10 px-4" :disabled="isApprovingCanvasser">Cancel</Button>
        </DialogClose>
        <Button type="submit" form="applyApplication" :loading="isApprovingCanvasser"> Approve &amp; Assign </Button>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { toTypedSchema } from '@vee-validate/zod';
import { useForm } from 'vee-validate';
import { useApproveCanvasser } from '~/mutations/applications';
import type {
  UserApplicationListItem,
  ProjectType,
  SignatureUpcomingManagerPricing,
  CanvassingUpcomingManagerPricing,
} from '~/client';
import { buildAssignmentInfoSchema } from '~/constants/validationSchemas/assignmentInfo';
import { defaultPositionForRole } from '~/constants/assignments/positionDefaults';

interface Props {
  application: UserApplicationListItem;
  payment: SignatureUpcomingManagerPricing | CanvassingUpcomingManagerPricing;
  projectId: string;
  projectName: string;
  projectType: ProjectType;
  paymentEnabled: boolean;
}

const props = defineProps<Props>();

const isVisible = ref<boolean>(false);

const increasedPayRateEnabled = computed(() => isIncreasedPayRateApplicable(props.payment));

const schema = computed(() =>
  toTypedSchema(
    buildAssignmentInfoSchema({
      projectType: props.projectType,
      paymentEnabled: props.paymentEnabled,
      increasedPayRateEnabled: increasedPayRateEnabled.value,
      payRateApplicable: true,
      // Applicants are always regular canvassers here (see :user-role above).
      canvassingAppUsernameApplicable: true,
      mode: 'create',
    })
  )
);

const { handleSubmit, setValues, resetForm } = useForm({
  validationSchema: schema,
});

const { approveCanvasser, isApprovingCanvasser } = useApproveCanvasser();

const onApply = handleSubmit(async (values) => {
  await approveCanvasser({
    user_id: props.application.user_id,
    project_id: props.projectId,
    price_per_signature: props.projectType === 'signature' ? (values.rate ?? null) : null,
    price_per_hour: props.projectType === 'canvassing' ? (values.rate ?? null) : null,
    canvassing_application_user_email: props.projectType === 'canvassing' ? (values.canvasser_in_app ?? null) : null,
    assignment_type: values.assignment_type ?? null,
    increased_price_per_hour: props.projectType === 'canvassing' ? (values.increased_price_per_hour ?? null) : null,
    position: values.position ?? null,
  });
  isVisible.value = false;
});

function onOpenUpdate(newValue: boolean) {
  if (!newValue) {
    resetForm();
    return;
  }
  if (!props.payment) return;
  setValues(
    {
      assignment_type: 'local',
      rate: isUpcomingSignaturePricingForManagerOrAdmin(props.payment)
        ? props.payment.for_canvasser_per_signature != null
          ? String(props.payment.for_canvasser_per_signature)
          : null
        : props.payment.for_canvasser_per_hour != null
          ? String(props.payment.for_canvasser_per_hour)
          : null,
      increased_price_per_hour:
        !isUpcomingSignaturePricingForManagerOrAdmin(props.payment) &&
        props.payment.increased_pay_rate_enabled &&
        props.payment.increased_for_canvasser_per_hour != null
          ? String(props.payment.increased_for_canvasser_per_hour)
          : null,
      canvasser_in_app: null,
      position: defaultPositionForRole('canvasser'),
    },
    false
  );
}
</script>

<style scoped lang="scss"></style>
