import { getUpcomingProjectDetails } from '~/client';
import { useRoute } from 'vue-router';

export const useApplicationDetails = defineQuery(() => {
  const route = useRoute('applications-id');
  const projectId = computed(() => route.params.id as string);

  const {
    data: projectDetails,
    error,
    isLoading,
  } = useQuery({
    key: () => ['applications.details', projectId.value],
    query: () => getUpcomingProjectDetails({ composable: '$fetch', path: { project_id: projectId.value } }),
    enabled: () => !!projectId.value,
    staleTime: 0,
  });

  return {
    projectDetails,
    error,
    isLoading,
  };
});
