<template>
  <!--TODO: create component ConfirmationDialogForm.vue-->
  <Dialog v-model:open="isVisible">
    <DialogTrigger as-child>
      <slot />
    </DialogTrigger>
    <DialogContent class="gap-6 max-w-xs sm:max-w-sm md:max-w-lg">
      <DialogHeader class="gap-y-2 text-left">
        <DialogTitle class="text-xl">Reject Application?</DialogTitle>
        <DialogDescription />
        <form id="rejectApplication" class="pt-2" @submit.prevent="onReject">
          <div class="flex flex-col gap-2 text-accent-foreground">
            <p>
              Do you really want to reject <span class="font-bold">{{ username(application) }}</span>
              's application for this project?
            </p>
            <div class="flex flex-col gap-4">
              <p>Please specify the reason.</p>
              <FormField
                v-slot="{ componentField }"
                :validate-on-model-update="false"
                :validate-on-blur="false"
                name="rejection_reason"
              >
                <FormItem class="flex-auto">
                  <FormControl>
                    <RadioGroup
                      id="rejection_reason"
                      v-model="rejectReason"
                      :default-value="null"
                      class="flex flex-col gap-4"
                      v-bind="componentField"
                    >
                      <div v-for="item in rejectReasons" :key="item" class="flex items-center gap-2">
                        <RadioGroupItem :id="item" :value="item" />
                        <Label :for="item">{{ item }}</Label>
                      </div>
                    </RadioGroup>
                    <FormMessage />
                  </FormControl>
                </FormItem>
              </FormField>
              <FormField
                v-if="rejectReason === 'Other'"
                v-slot="{ componentField }"
                :validate-on-model-update="false"
                :validate-on-blur="false"
                name="rejection_reason_other"
              >
                <FormItem class="flex-auto">
                  <FormControl>
                    <Input id="rejection_reason_other" type="input" v-bind="componentField" />
                    <FormMessage />
                  </FormControl>
                </FormItem>
              </FormField>
            </div>
          </div>
        </form>
      </DialogHeader>
      <DialogFooter>
        <div class="flex gap-2">
          <DialogClose as-child>
            <Button variant="outline" class="h-10 px-4" :disabled="isRejectingCanvasser">Cancel</Button>
          </DialogClose>
          <Button
            variant="destructive"
            class="h-10 px-4"
            :loading="isRejectingCanvasser"
            type="submit"
            form="rejectApplication"
            >Reject Application</Button
          >
        </div>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { rejectReasons } from '~/constants/applications/details';
import { toTypedSchema } from '@vee-validate/zod';
import * as z from 'zod';
import { useForm } from 'vee-validate';
import { useRejectCanvasser } from '~/mutations/applications';
import type { UserApplicationListItem, ProjectApplicationRejectRequest } from '~/client';

const isVisible = ref<boolean>(false);
interface Props {
  application: UserApplicationListItem;
  projectId: string;
}

const props = defineProps<Props>();

const rejectReason = ref<string | null>(null);

const formSchema = toTypedSchema(
  z.object({
    rejection_reason: z
      .string()
      .default('')
      .refine(
        (val) => {
          return val && val.length > 0;
        },
        { message: 'Rejection reason is required' }
      ),
    rejection_reason_other: z
      .string()
      .default('')
      .refine(
        (val) => {
          if (rejectReason.value !== 'Other') return true;
          else return val && val.trim().length > 0;
        },
        { message: 'Other option is required' }
      ),
  })
);

const { handleSubmit } = useForm({
  validationSchema: formSchema,
});

const onReject = handleSubmit(async (values) => {
  const body: ProjectApplicationRejectRequest = {
    user_id: props.application.user_id,
    project_id: props.projectId,
    rejection_reason: rejectReason.value === 'Other' ? values.rejection_reason_other : values.rejection_reason,
  };
  await rejectCanvasser(body);
  isVisible.value = false;
});

const { rejectCanvasser, isRejectingCanvasser } = useRejectCanvasser();
</script>

<style scoped lang="scss"></style>
