import { projectApplicationReject, type ProjectApplicationRejectRequest } from '~/client';

export const useRejectCanvasser = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync: rejectCanvasser, asyncStatus } = useMutation({
    mutation: (rejectData: ProjectApplicationRejectRequest) =>
      projectApplicationReject({
        composable: '$fetch',
        body: {
          ...rejectData,
        },
      }),
    onSuccess: async (data, { project_id }) => {
      queryCache.invalidateQueries({ key: ['project-tabs-status'], exact: false });
      queryCache.invalidateQueries({ key: ['applications.applicants'], exact: false });
      queryCache.invalidateQueries({ key: ['applications.details'], exact: false });
    },
    onError: (error, { project_id }) => {
      queryCache.invalidateQueries({ key: ['applications.applicants'], exact: false });
      console.error('Error rejecting canvasser:', error);
      showToastError(error);
    },
  });

  return {
    rejectCanvasser,
    isRejectingCanvasser: computed(() => asyncStatus.value === 'loading'),
  };
});
