<template>
  <ApplicationsDetailsFilters :params="params" />
  <FilterTabsNav :items="statusTabs" rounded show-zero-count stretched />
  <Card>
    <CardContent class="!p-0 md:!p-0 overflow-hidden">
      <ApplicationsTable
        :applications="usersApplications"
        :is-loading="isLoading"
        :error="error"
        :refetch="refetch"
        :page="params.page"
        :size="params.size"
        :total="totalCount"
        :project-id="projectId"
        :payment
        :project-name
        :project-type
        :payment-enabled
      />
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import {
  type ProjectType,
  type UserApplicationSortBy,
  type SignatureUpcomingManagerPricing,
  type CanvassingUpcomingManagerPricing,
  getUserApplications,
  type ProjectApplicationStatus,
  type SortType,
  type UserApplicationListRequest,
} from '~/client';

const props = withDefaults(
  defineProps<{
    payment: SignatureUpcomingManagerPricing | CanvassingUpcomingManagerPricing;
    projectId: string;
    projectName: string;
    projectType: ProjectType;
    paymentEnabled: boolean;
  }>(),
  {
    projectName: '',
  }
);

const params = computed(() => {
  return {
    ...parsePagination(useRoute().query),
    project_id: props.projectId,
    sort_by: (useRoute().query.sort_by as UserApplicationSortBy) || 'name',
    sort_type: isSortType(useRoute().query.sort_type as string) ? (useRoute().query.sort_type as SortType) : 'asc',
    search_query: (useRoute().query.search_query as string) || undefined,
    statuses: processArrayQueryParameterFromUrl<ProjectApplicationStatus>(useRoute().query.statuses),
    onboarding_state: parseOnboardingStateFromQuery(useRoute().query),
  } satisfies UserApplicationListRequest;
});

const {
  data: usersApplications,
  error,
  isLoading,
  refetch,
} = useQuery({
  key: () => [
    'applications.applicants',
    { ...params.value, onboarding_state: serializeOnboardingStateForKey(useRoute().query) },
  ],
  query: () =>
    getUserApplications({
      composable: '$fetch',
      body: params,
    }),
  enabled: () => !!props.projectId,
  staleTime: 0,
});

const totalCount = computed(() => usersApplications.value?.total_count ?? 0);
const statusCounts = computed(() => usersApplications.value?.status_count ?? {});
const allCount = computed(
  () => (statusCounts.value.applied || 0) + (statusCounts.value.rejected || 0) + (statusCounts.value.approved || 0)
);

const statusTabs = computed<NavigationItem[]>(() =>
  buildMultiSelectStatusTabs<ProjectApplicationStatus>({
    source: filteredApplicationStatusesForTabs.value,
    current: params.value.statuses ?? [],
    allCount: allCount.value,
    counts: statusCounts.value,
    buildTo: (next) => ({
      name: useRoute().name,
      params: { id: props.projectId },
      query: { ...useRoute().query, page: 1, statuses: next.length ? next : undefined },
    }),
  })
);
</script>

<style scoped lang="scss"></style>
